<?php use App\Core\Authorization; ?>
<div class="page-heading"><div><p class="eyebrow">Analysis</p><h1>Reports</h1><p>Review operational records and export them for local use.</p></div><?php if(Authorization::allows('reports.export')):?><a class="button primary" href="<?=e(url('/reports/export?'.http_build_query(['type'=>$type,'from'=>$from,'to'=>$to])))?>">Export CSV</a><?php endif;?></div>
<form method="get" class="report-filter"><label>Report<select name="type"><?php foreach($reportTypes as $value=>$label):?><option value="<?=$value?>" <?=$type===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><button class="button">Generate</button></form>
<section class="card table-card"><div class="table-heading"><h2><?=count($rows)?> records</h2></div><table><thead><tr><?php foreach($columns as $label):?><th scope="col"><?=e($label)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach(array_keys($columns) as $key):?><td><?=e((string)($row[$key]??''))?></td><?php endforeach;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="<?=count($columns)?>" class="empty">No records match this report.</td></tr><?php endif;?></tbody></table></section>
